D:   joisino’s travel

 　N が200 以下なので、町と町の間の距離はワーシャルフロイド法で求めて問題ない。
　そして、ri の並べ方だが、こちらもR が8 以下なので、すべての順列について試して
みることができる。
　順列の生成方法はいろいろ考えられるが、深さ優先探索を用いても十分間に合う。
　また、C++におけるnext permutation のような標準ライブラリを用いて解くのもよい
だろう。


#include <cstdio >
using namespace std;
#define INF (1<<29)

int N,M,R;
int d[201][201];
int r[9];
int A,B,C;
int res;
bool used [9];


                                      2

void dfs(int c,int las ,int dist)
{
        if(c==R+1)
          {
                 if(res >dist)res=dist;
                 return;
          }
        for(int i=1;i<=R;i++)if(! used[i])
          {
                 used[i]= true;
                 if(las ==-1) dfs(c+1,i ,0);
                 else dfs(c+1,i,dist+d[r[las ]][r[i]]);
                 used[i]= false;
          }
}



int main ()
{
        scanf("%d%d%d" ,&N,&M,&R);
        for(int i=1;i<=N;i++) for(int j=1;j<=N;j++)if(i!=j)d[i][j]=INF;
        for(int i=1;i<=R;i++) scanf("%d" ,&r[i]);
        for(int i=1;i<=M;i++)
          {
                scanf("%d%d%d" ,&A,&B,&C);
                if(d[A][B]>C)d[A][B]=d[B][A]=C;
          }
        for(int k=1;k<=N;k++)
                 for(int i=1;i<=N;i++)
                         for(int j=1;j<=N;j++)
                                if(d[i][j]>d[i][k]+d[k][j])
                                        d[i][j]=d[i][k]+d[k][j];
        res=INF;
         dfs (1,-1,0);
        printf("%d\n",res);
}





